use std::fs;
use std::io::{self, Write};
use std::fmt;

// ---- Custom error type ----
#[derive(Debug)]
enum AppError {
    Io(io::Error),
    InvalidInput(String),
    NotFound(String),
    Processing(String),
}

impl fmt::Display for AppError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            AppError::Io(e) => write!(f, "I/O error: {}", e),
            AppError::InvalidInput(msg) => write!(f, "Invalid input: {}", msg),
            AppError::NotFound(msg) => write!(f, "Not found: {}", msg),
            AppError::Processing(msg) => write!(f, "Processing error: {}", msg),
        }
    }
}

impl std::error::Error for AppError {}

impl From<io::Error> for AppError {
    fn from(err: io::Error) -> Self {
        AppError::Io(err)
    }
}

type AppResult<T> = Result<T, AppError>;

// ---- Production-ready file processor ----
struct FileProcessor {
    input_path: String,
    output_path: String,
    verbose: bool,
}

impl FileProcessor {
    fn new(input_path: String, output_path: String, verbose: bool) -> Self {
        FileProcessor {
            input_path,
            output_path,
            verbose,
        }
    }

    fn process(&self) -> AppResult<()> {
        // Validate input
        if self.input_path.is_empty() {
            return Err(AppError::InvalidInput("Input path is empty".to_string()));
        }

        if self.output_path.is_empty() {
            return Err(AppError::InvalidInput("Output path is empty".to_string()));
        }

        // Check if input exists
        if !std::path::Path::new(&self.input_path).exists() {
            return Err(AppError::NotFound(format!("File '{}' not found", self.input_path)));
        }

        // Read and process
        let content = self.read_file()?;
        let processed = self.process_content(&content)?;
        self.write_file(&processed)?;

        Ok(())
    }

    fn read_file(&self) -> AppResult<String> {
        if self.verbose {
            eprintln!("Reading from: {}", self.input_path);
        }

        match fs::read_to_string(&self.input_path) {
            Ok(content) => {
                if self.verbose {
                    eprintln!("Read {} bytes", content.len());
                }
                Ok(content)
            }
            Err(e) => Err(AppError::Io(e))
        }
    }

    fn process_content(&self, content: &str) -> AppResult<String> {
        if content.is_empty() {
            return Err(AppError::Processing("Input file is empty".to_string()));
        }

        // Example: Count lines and words
        let lines = content.lines().count();
        let words = content.split_whitespace().count();
        let chars = content.chars().count();

        Ok(format!(
            "Line count: {}\nWord count: {}\nCharacter count: {}\n\nOriginal content:\n{}",
            lines, words, chars, content
        ))
    }

    fn write_file(&self, content: &str) -> AppResult<()> {
        if self.verbose {
            eprintln!("Writing to: {}", self.output_path);
        }

        fs::write(&self.output_path, content)?;

        if self.verbose {
            eprintln!("Done!");
        }

        Ok(())
    }
}

// ---- Main with error handling ----
fn main() -> AppResult<()> {
    let args: Vec<String> = std::env::args().collect();

    // Simple argument parsing
    let verbose = args.contains(&"-v".to_string()) || args.contains(&"--verbose".to_string());
    let input = args.get(1).cloned().unwrap_or_else(|| "input.txt".to_string());
    let output = args.get(2).cloned().unwrap_or_else(|| "output.txt".to_string());

    let processor = FileProcessor::new(input, output, verbose);

    match processor.process() {
        Ok(()) => {
            println!("✅ Processing completed successfully!");
            Ok(())
        }
        Err(AppError::NotFound(msg)) => {
            eprintln!("❌ Error: {}", msg);
            eprintln!("💡 Hint: Check the file path and try again.");
            Err(AppError::NotFound(msg))
        }
        Err(AppError::InvalidInput(msg)) => {
            eprintln!("❌ Error: {}", msg);
            eprintln!("💡 Hint: Make sure both input and output paths are provided.");
            Err(AppError::InvalidInput(msg))
        }
        Err(e) => {
            eprintln!("❌ Error: {}", e);
            Err(e)
        }
    }
}

